?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Activate Alumni Account | AYISEC</title><link rel="icon" type="image/png" href="logo/logo-transparent.png"><style>:root{--n:#102b4b;--t:#08766f;--p:#f4f7fb;--l:#dce5ed}*{box-sizing:border-box}body{margin:0;background:var(--p);font:15px Arial;color:#1e293b}.wrap{max-width:760px;margin:auto;padding:40px 18px}.hero{background:linear-gradient(120deg,var(--n),var(--t));color:#fff;border-radius:20px;padding:30px}.hero h1{font:600 31px Georgia,serif;margin:7px 0}.hero p{margin:0;color:#dcecf0;line-height:1.55}.card{margin-top:20px;padding:24px;border:1px solid var(--l);border-radius:16px;background:#fff}.card h2{font:600 23px Georgia,serif;color:var(--n);margin:0 0 7px}.note{color:#64748b;line-height:1.55}.form{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:18px}.form label{font-size:12px;font-weight:bold;color:#475569}.form input{display:block;width:100%;margin-top:5px;border:1px solid #c8d6e2;border-radius:9px;padding:12px;font:inherit}.wide{grid-column:span 2}.consent{display:flex;gap:9px;align-items:flex-start;font-size:13px!important;font-weight:normal!important;line-height:1.45}.consent input{display:inline;width:auto;margin:2px 0 0}button{border:0;border-radius:9px;background:var(--t);color:#fff;padding:13px 16px;font-weight:bold;cursor:pointer}.error{background:#fff0f0;color:#a12626;padding:13px;border-radius:9px;margin-top:16px}@media(max-width:600px){.wrap{padding:22px 12px}.hero,.card{padding:21px}.form{grid-template-columns:1fr}.wide{grid-column:span 1}}</style></head><body><main class="wrap"><section class="hero"><small>WELCOME TO AYOSA</small><h1>Your student journey continues.</h1><p>Hello <?php echo alumni_safe($alumnus['fullname']);?>. Activate your Alumni profile to stay connected with AYISEC after graduation.</p></section><?php if($message!==''){?><p class="error"><?php echo alumni_safe($message);?></p><?php }?><section class="card"><h2>Complete your Alumni profile</h2><p class="note">Your school account and academic history remain protected. Choose how the Alumni community may contact and recognise you.</p><form method="post" class="form"><input type="hidden" name="csrf" value="<?php echo alumni_safe($_SESSION['alumni_activation_csrf']);?>"><label>Email address<input type="email" name="email" value="<?php echo alumni_safe($alumnus['email']);?>"></label><label>Mobile number<input name="mobile" value="<?php echo alumni_safe($alumnus['mobile']);?>"></label><label>Create Alumni password<input type="password" name="password" minlength="8" required></label><label>Repeat password<input type="password" name="repeatpassword" minlength="8" required></label><label class="wide consent"><input type="checkbox" name="directoryconsent" value="1"> I agree to appear in the private verified Alumni Directory.</label><label class="wide consent"><input type="checkbox" name="photoconsent" value="1"> I agree that verified Alumni may see my profile photo if I add one later.</label><label class="wide consent"><input type="checkbox" name="chatconsent" value="1"> I want access to private Alumni conversations.</label><label class="wide consent"><input type="checkbox" name="smsoptin" value="1"> I agree to receive AYISEC Alumni updates by SMS.</label><div class="wide"><button name="activate">Activate my Alumni account</button></div></form></section></main></body></html>
